/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    boolean ret;

    ret = super();

    return ret;
}

/// <summary>
/// Find NVOrderTypeTable by RecId
/// </summary>
/// <param name="_recId">RecId of the order type</param>
/// <param name="_forUpdate">Select for update flag</param>
/// <returns>NVOrderTypeTable record</returns>
public static NVOrderTypeTable find(RecId _recId, boolean _forUpdate = false)
{
    NVOrderTypeTable orderTypeTable;

    if (!_recId)
    {
        return orderTypeTable;
    }

    if (_forUpdate)
    {
        orderTypeTable.selectForUpdate(_forUpdate);
    }

    select firstonly orderTypeTable
        where orderTypeTable.RecId == _recId;

    return orderTypeTable;
}

/// <summary>
/// Find NVOrderTypeTable by OrderType enum value
/// </summary>
/// <param name="_orderType">Order type enum value</param>
/// <param name="_forUpdate">Select for update flag</param>
/// <returns>NVOrderTypeTable record</returns>
public static NVOrderTypeTable findByOrderType(NVOrderType _orderType, boolean _forUpdate = false)
{
    NVOrderTypeTable orderTypeTable;

    if (_orderType == NVOrderType::None)
    {
        return orderTypeTable;
    }

    if (_forUpdate)
    {
        orderTypeTable.selectForUpdate(_forUpdate);
    }

    select firstonly orderTypeTable
        where orderTypeTable.OrderType == _orderType;

    return orderTypeTable;
}

/// <summary>
/// Check if order type exists by RecId
/// </summary>
/// <param name="_recId">RecId of the order type</param>
/// <returns>True if exists</returns>
public static boolean exist(RecId _recId)
{
    return _recId && (select firstonly RecId from NVOrderTypeTable
                  where NVOrderTypeTable.RecId == _recId).RecId != 0;
}

/// <summary>
/// Get related NVOrderTypeGroup record
/// </summary>
/// <returns>NVOrderTypeGroup record</returns>
public NVOrderTypeGroup group()
{
    return NVOrderTypeGroup::find(this.GroupRecId);
}
